"""TK-008: сверка района/точки по всем 60 местам выборки TK-007 по C:/verger-data/pilot/tk008/PROTOCOL.md.
Запуск: python tools/tk008_area60.py   (сырьё: raw60.json — кэш запросов Nominatim; итог: area60.json)
"""
import json, math, os, re, sys, time, unicodedata, urllib.parse, urllib.request

D7 = 'C:/verger-data/pilot/tk007/'
D8 = 'C:/verger-data/pilot/tk008/'
S = json.load(open(D7 + 'sample60.json', encoding='utf8'))
MC = {c['i']: c for c in json.load(open(D7 + 'manual_checks.json', encoding='utf8'))['checks']}
RAW = D8 + 'raw60.json'
raw = json.load(open(RAW, encoding='utf8')) if os.path.exists(RAW) else {}
UA = {'User-Agent': 'verger-tk008/1.0 (research)'}
FIELDS = ['suburb', 'neighbourhood', 'quarter', 'city_district', 'borough', 'district', 'city_block', 'village', 'town', 'municipality', 'county']
NOISE = {'district', 'quarter', 'arrondissement', 'ward', 'borough', 'neighborhood', 'neighbourhood', 'area', 'the', 'de', 'di', 'la', 'le', 'el', 'of', 'del', 'des', 'du'}
STOP = {'the', 'bar', 'restaurant', 'le', 'la', 'el', 'de', 'di', 'wine', 'cocktail', 'cocktails', 'and', 'ristorante', 'enoteca', 'club'}


def norm(s):
    s = unicodedata.normalize('NFKD', s.lower())
    s = ''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9 ]', ' ', s).split()


def sig(s):
    return set(norm(s)) - NOISE


def same(a, b):
    A, B = set(norm(a)), set(norm(b))
    if not A or not B:
        return False
    ka, kb = A - STOP, B - STOP
    if ka and kb:
        return len(ka & kb) / min(len(ka), len(kb)) >= 0.6
    return A == B


def get(key, url):
    if key in raw:
        return raw[key]
    r = None
    for _ in range(3):
        try:
            r = json.load(urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=25))
            break
        except Exception:
            time.sleep(4)
    raw[key] = r
    json.dump(raw, open(RAW, 'w', encoding='utf8'), ensure_ascii=False)
    time.sleep(1.1)
    return r


def hav(a, b, c, d):
    p = math.pi / 180
    x = math.sin((c - a) * p / 2) ** 2 + math.cos(a * p) * math.cos(c * p) * math.sin((d - b) * p / 2) ** 2
    return 12742000 * math.asin(math.sqrt(x))


def q(d):
    return urllib.parse.urlencode(d)


def city_of(p):
    # mapsQuery = "<имя> <город>, <страна>"
    m = p['mapsQuery']
    m = m.replace(p['name'], '', 1).strip()
    return m


rows = []
for i, p in enumerate(S):
    la, ln, cc = p['lat'], p['lng'], (p.get('countryCode') or '').lower()
    pid = p['placeId']
    src = 'Overture' if pid.startswith('ov_') else 'Foursquare' if pid.startswith('fsq_') else 'Google/other'
    rv18 = get(f'rv18|{i}', 'https://nominatim.openstreetmap.org/reverse?' + q({'lat': la, 'lon': ln, 'zoom': 18, 'format': 'jsonv2', 'addressdetails': 1}))
    rv14 = get(f'rv14|{i}', 'https://nominatim.openstreetmap.org/reverse?' + q({'lat': la, 'lon': ln, 'zoom': 14, 'format': 'jsonv2', 'addressdetails': 1}))
    names = []
    for r in (rv18, rv14):
        a = (r or {}).get('address') or {}
        for f in FIELDS:
            if a.get(f) and a[f] not in names:
                names.append(a[f])
    area = p['area']
    # правило 2.1
    sa = sig(area)
    m1 = bool(sa) and any((sa <= sig(n)) or (sig(n) and sig(n) <= sa) for n in names)
    # правило 2.2
    cityq = city_of(p)
    lab = get(f'lab|{i}', 'https://nominatim.openstreetmap.org/search?' + q({'q': f'{area}, {cityq}', 'format': 'json', 'limit': 1, 'countrycodes': cc} if cc else {'q': f'{area}, {cityq}', 'format': 'json', 'limit': 1}))
    lab = (lab or [None])[0]
    dist_lab = bbox_in = None
    if lab:
        dist_lab = hav(la, ln, float(lab['lat']), float(lab['lon']))
        bb = [float(x) for x in lab['boundingbox']]
        bbox_in = bb[0] <= la <= bb[1] and bb[2] <= ln <= bb[3]
    m2 = bool(lab) and (bbox_in or dist_lab <= 1000)
    border = (not m1) and bool(lab) and not m2 and dist_lab <= 2000
    # (в) положение места
    d = 0.05
    fw = get(f'fw|{i}', 'https://nominatim.openstreetmap.org/search?' + q({'q': p['mapsQuery'], 'format': 'json', 'limit': 5, 'addressdetails': 1, 'viewbox': f'{ln-d},{la+d},{ln+d},{la-d}'}))
    hit = None
    for x in fw or []:
        nm = x.get('name') or x['display_name'].split(',')[0]
        if same(p['name'], nm) and x.get('class') not in ('boundary', 'place', 'highway'):
            hit = {'osm': f"{x['osm_type']}/{x['osm_id']}", 'url': f"https://www.openstreetmap.org/{x['osm_type']}/{x['osm_id']}", 'name': nm,
                   'lat': float(x['lat']), 'lon': float(x['lon']), 'display': x['display_name'], 'dist_m': round(hav(la, ln, float(x['lat']), float(x['lon'])))}
            break
    mc = MC.get(i, {})
    # класс
    match = m1 or m2
    off = bool(hit) and hit['dist_m'] > 300
    if off:
        cls = 'B'
    elif match:
        cls = 'ок'
    elif border:
        cls = 'неясно'
    elif hit:
        cls = 'A'
    else:
        cls = 'A/B?'
    rows.append({'i': i, 'name': p['name'], 'placeId': pid, 'coord_source': src, 'area_shown': area, 'lat': la, 'lng': ln,
                 'point_districts': names, 'match_names': m1, 'label_geocode': {'lat': lab and float(lab['lat']), 'lon': lab and float(lab['lon']), 'dist_m': dist_lab and round(dist_lab), 'bbox_has_point': bbox_in} if lab else None,
                 'match_label_geocode': m2, 'border': border, 'real_place_osm': hit, 'tk007_why': mc.get('why'), 'tk007_url': mc.get('url'), 'class': cls})
    print(i, p['name'][:30], '|', area, '|', names[:3], '|', cls, hit and hit['dist_m'], flush=True)
json.dump(rows, open(D8 + 'area60.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
open(D8 + 'AREA60_DONE', 'w').write('ok')

